{"code":"import os, re

# Read config
with open('/opt/data/config.yaml') as f:
    config = f.read()

# Read .env
env_path = '/opt/data/.env'
env_vars = {}
if os.path.exists(env_path):
    with open(env_path) as f:
        for line in f:
            line = line.strip()
            if '=' in line and not line.startswith('#'):
                k, v = line.split('=', 1)
                env_vars[k.strip()] = v.strip()

# Detect providers from .env keys
providers = []
for k in env_vars:
    kl = k.lower()
    if 'openrouter' in kl:
        providers.append(('OpenRouter', True, 'Key found'))
    elif 'openai' in kl:
        providers.append(('OpenAI', True, 'Key found'))
    elif 'anthropic' in kl:
        providers.append(('Anthropic', True, 'Key found'))
    elif 'google' in kl or 'gemini' in kl:
        providers.append(('Google Gemini', True, 'Key found'))
    elif 'deepseek' in kl:
        providers.append(('DeepSeek', True, 'Key found'))
    elif 'hugging' in kl or 'hf' in kl:
        providers.append(('Hugging Face', True, 'Key found'))
    elif 'nvidia' in kl or 'nim' in kl:
        providers.append(('NVIDIA NIM', True, 'Key found'))
    elif 'cohere' in kl:
        providers.append(('Cohere', True, 'Key found'))
    elif 'groq' in kl:
        providers.append(('Groq', True, 'Key found'))
    elif 'together' in kl:
        providers.append(('Together', True, 'Key found'))
    elif 'mistral' in kl:
        providers.append(('Mistral', True, 'Key found'))
    elif 'xai' in kl or 'x.ai' in kl:
        providers.append(('xAI', True, 'Key found'))

# Check config for provider/model config
print("=== ENVIRONMENT VARIABLES (keys detected) ===")
for k in sorted(env_vars.keys()):
    if any(word in k.lower() for word in ['key', 'token', 'secret', 'api']):
        masked = env_vars[k][:8] + '...' + env_vars[k][-4:] if len(env_vars[k]) > 12 else env_vars[k][:4] + '...'
        print(f"  {k} = {masked}")

print()

# Check config yaml for model config
print("=== CONFIG.YAML - Model/Provider sections ===")
in_provider = False
in_model = False
for line in config.split('\n'):
    if 'provider' in line.lower() and ':' in line:
        in_provider = True
        print(f"  {line}")
        continue
    if in_provider and ('model' in line.lower() and ':' in line):
        in_model = True
        print(f"  {line}")
        continue
    if in_provider and in_model:
        if line.strip() and not line.startswith(' '):
            in_provider = False
            in_model = False
        elif line.strip():
            print(f"  {line}")
    if in_provider and not in_model and line.strip():
        if ':' in line and not line.startswith(' '):
            in_provider = False
        else:
            print(f"  {line}")

print()
print("=== KEY PROVIDERS & TIER STATUS ===")
print(f"  OpenRouter:    Key={os.path.exists(env_path) and 'OPENROUTER_API_KEY' in env_vars} (Free tier available: many models)")
print(f"  Hugging Face:  Key={os.path.exists(env_path) and 'HUGGINGFACE_API_KEY' in env_vars} (Free tier: serverless inference)")
print(f"  NVIDIA NIM:    Key={os.path.exists(env_path) and 'NVIDIA_API_KEY' in env_vars} (Free tier: rate-limited)")
print(f"  Nous Portal:   Built-in / OAuth (Free: Hermes default)")
print(f"  Google Gemini: Key={os.path.exists(env_path) and 'GEMINI_API_KEY' in env_vars} (PAID - requires permission)")
print(f"  DeepSeek:      Key={os.path.exists(env_path) and 'DEEPSEEK_API_KEY' in env_vars} (PAID - requires permission)")
print(f"  OpenAI:        Key={os.path.exists(env_path) and 'OPENAI_API_KEY' in env_vars}")
print(f"  Anthropic:     Key={os.path.exists(env_path) and 'ANTHROPIC_API_KEY' in env_vars}")

# Current active model
print()
print(f"=== CURRENT ACTIVE SETUP ===")
for line in config.split('\n'):
    if 'provider:' in line and not line.strip().startswith('#'):
        print(f"  {line.strip()}")
