{"code":"import subprocess, json

# 1. OpenRouter - check models, filter free ones
print("=" * 70)
print("1. OPENROUTER FREE TIER MODELS")
print("=" * 70)
# Use curl to fetch models from OpenRouter
r = subprocess.run(['curl', '-s', 'https://openrouter.ai/api/v1/models'], capture_output=True, text=True, timeout=15)
if r.returncode == 0:
    data = json.loads(r.stdout)
    free_models = []
    for m in data.get('data', []):
        # Free models typically have pricing at $0 or are marked as free
        pricing = m.get('pricing', {})
        prompt_price = float(pricing.get('prompt', '1'))
        completion_price = float(pricing.get('completion', '1'))
        if prompt_price == 0 and completion_price == 0:
            free_models.append({
                'id': m['id'],
                'name': m.get('name', m['id']),
                'context': m.get('context_length', '?')
            })

    print(f"Total free models: {len(free_models)}")
    for m in sorted(free_models, key=lambda x: x['id']):
        print(f"  • {m['id']} (context: {m['context']})")
else:
    print(f"Error: {r.stderr[:200]}")"}

